		ctl4[12], ctl4[13], ctl4[10]|ctl4[11],
		ctl4[15], ctl4[14], 1'b0,
		3'b0
	};

	assign iobus_iob_out =
		wcnsls_datai ? ~{ ctl4n, ctl3n, ctl2n, ctl1n } :
		36'b0;
