  result_lo = $signed(op1) / $signed(op2); 
  result_hi = $signed(op1) % $signed(op2); 
  end 
  1: begin 
  result_lo = op1 / op2; 
  result_hi = op1 % op2; 
  end 
  2: begin 
  {result_hi, result_lo} = $signed(op1) * $signed(op2); 
  end 
  3: begin 
  {result_hi, result_lo} = op1 * op2; 
  end 
  endcase 
  $display("\tR[lo] = %x (hex)", result_lo); 
  $display("\tR[hi] = %x (hex)", result_hi); 
  end 
 endmodule

